func TestConfigScopesListsCountersAndEffectiveState(t *testing.T) {
	_, handler := newTestRouter(t)
	// payments/prod: full v1 (2 items), gray v2 (3 items), rollback v1 -> v3, promote v2 -> v4.
	publish(t, handler, "payments", "prod", "", map[string]any{"a": 1, "b": 2})
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": 9, "b": 2, "c": 3})
	rollback(t, handler, "payments", "prod", 1)
	promote(t, handler, "payments", "prod", 2)
	// payments/staging: gray-only.
	publish(t, handler, "payments", "staging", "beta", map[string]any{"a": 1})

	recorder := doRequest(t, handler, http.MethodGet, "/config-scopes", nil)
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	body := decodeRawConfigScopesBody(t, recorder)
	if body.MatchedCount != 2 || len(body.Scopes) != 2 {
		t.Fatalf("body = %s", recorder.Body.String())
	}
	if body.Scopes[0].Namespace != "payments" || body.Scopes[0].Environment != "prod" {
		t.Fatalf("first scope = %+v", body.Scopes[0])
	}
	if body.Scopes[1].Environment != "staging" {
		t.Fatalf("second scope = %+v", body.Scopes[1])
	}

	prod := body.Scopes[0]
	if prod.VersionCount != 4 || prod.EffectiveVersion == nil || *prod.EffectiveVersion != 4 {
		t.Fatalf("prod = %+v", prod)
	}
	if prod.EffectiveItemCount != 3 {
		t.Fatalf("effectiveItemCount = %d, want 3", prod.EffectiveItemCount)
	}
	if prod.GrayVersionCount != 1 || prod.RollbackVersionCount != 1 || prod.PromotionVersionCount != 1 {
		t.Fatalf("prod counters = %+v", prod)
	}
	var latest struct {
		Version     int64   `json:"version"`
		GrayTag     *string `json:"grayTag"`
		RollbackOf  *int64  `json:"rollbackOf"`
		PromotionOf *int64  `json:"promotionOf"`
		Effective   bool    `json:"effective"`
	}
	if err := json.Unmarshal(prod.LatestVersion, &latest); err != nil {
		t.Fatalf("decode latest: %v", err)
	}
	if latest.Version != 4 || latest.GrayTag != nil || latest.RollbackOf != nil ||
		latest.PromotionOf == nil || *latest.PromotionOf != 2 || !latest.Effective {
		t.Fatalf("latest metadata = %s", string(prod.LatestVersion))
	}

	staging := body.Scopes[1]
	if staging.VersionCount != 1 || staging.EffectiveVersion != nil || staging.EffectiveItemCount != 0 {
		t.Fatalf("staging = %+v", staging)
	}
	if staging.GrayVersionCount != 1 || staging.RollbackVersionCount != 0 || staging.PromotionVersionCount != 0 {
		t.Fatalf("staging counters = %+v", staging)
	}
	if err := json.Unmarshal(staging.LatestVersion, &latest); err != nil {
		t.Fatalf("decode staging latest: %v", err)
	}
	if latest.Version != 1 || latest.GrayTag == nil || *latest.GrayTag != "beta" || latest.Effective {
		t.Fatalf("staging latest metadata = %s", string(staging.LatestVersion))
	}
}

