package api

import (
	"net/http"
	"strconv"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/config-center-api/internal/store"
)

const (
	defaultConfigScopePageSize = 100
	maxConfigScopePageSize     = 500
)

// ConfigScope summarizes the version history of one namespace and environment.
type ConfigScope struct {
	Namespace             string      `json:"namespace"`
	Environment           string      `json:"environment"`
	VersionCount          int64       `json:"versionCount"`
	LatestVersion         VersionInfo `json:"latestVersion"`
	EffectiveVersion      *int64      `json:"effectiveVersion"`
	EffectiveItemCount    int64       `json:"effectiveItemCount"`
	GrayVersionCount      int64       `json:"grayVersionCount"`
	RollbackVersionCount  int64       `json:"rollbackVersionCount"`
	PromotionVersionCount int64       `json:"promotionVersionCount"`
}

// ConfigScopesResponse is the read-only paged scope listing. The cursor fields are null whenever
// the current page is empty.
type ConfigScopesResponse struct {
	MatchedCount         int           `json:"matchedCount"`
	Scopes               []ConfigScope `json:"scopes"`
	HasMore              bool          `json:"hasMore"`
	NextAfterNamespace   *string       `json:"nextAfterNamespace"`
	NextAfterEnvironment *string       `json:"nextAfterEnvironment"`
}

// handleConfigScopes lists every scope that owns version history. It is strictly read-only: no
// version is created and publish, gray, promotion, rollback and effective state never change.
func (s *server) handleConfigScopes(c *gin.Context) {
	filter := store.ScopeFilter{
		Namespace:   c.Query("namespace"),
		Environment: c.Query("environment"),
	}
	limit := defaultConfigScopePageSize
	if rawLimit, hasLimit := c.GetQuery("limit"); hasLimit {
		parsed, ok := parseConfigScopePageSize(rawLimit)
		if !ok {
			writeError(c, http.StatusBadRequest, "INVALID_PAGE_SIZE", "limit must be a decimal integer between 1 and 500")
			return
		}
		limit = parsed
	}
	rawAfterNamespace, hasAfterNamespace := c.GetQuery("afterNamespace")
	rawAfterEnvironment, hasAfterEnvironment := c.GetQuery("afterEnvironment")
	if hasAfterNamespace != hasAfterEnvironment ||
		(hasAfterNamespace && (rawAfterNamespace == "" || rawAfterEnvironment == "")) {
		writeError(c, http.StatusBadRequest, "INVALID_CURSOR", "afterNamespace and afterEnvironment must be supplied together as non-empty values")
		return
	}
	if rawHasEffective, hasEffective := c.GetQuery("hasEffective"); hasEffective {
		switch rawHasEffective {
		case "true":
			filter.HasEffective = true
			filter.HasEffectiveFilter = true
		case "false":
			filter.HasEffective = false
			filter.HasEffectiveFilter = true
		default:
			writeError(c, http.StatusBadRequest, "INVALID_EFFECTIVE_FILTER", "hasEffective must be true or false")
			return
		}
	}

	page, err := s.store.ListScopes(c.Request.Context(), filter, rawAfterNamespace, rawAfterEnvironment, limit)
	if err != nil {
		writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
		return
	}

	scopes := make([]ConfigScope, 0, len(page.Scopes))
	for _, scope := range page.Scopes {
		scopes = append(scopes, ConfigScope{
			Namespace:             scope.Namespace,
			Environment:           scope.Environment,
			VersionCount:          scope.VersionCount,
			LatestVersion:         toVersionInfo(scope.Latest, scope.EffectiveVersion),
			EffectiveVersion:      intPtrOrNil(scope.EffectiveVersion),
			EffectiveItemCount:    scope.EffectiveItemCount,
			GrayVersionCount:      scope.GrayVersionCount,
			RollbackVersionCount:  scope.RollbackVersionCount,
			PromotionVersionCount: scope.PromotionVersionCount,
		})
	}
	response := ConfigScopesResponse{
		MatchedCount: int(page.Total),
		Scopes:       scopes,
		HasMore:      page.HasMore,
	}
	if len(scopes) > 0 {
		last := scopes[len(scopes)-1]
		response.NextAfterNamespace = &last.Namespace
		response.NextAfterEnvironment = &last.Environment
	}
	c.JSON(http.StatusOK, response)
}

func parseConfigScopePageSize(raw string) (int, bool) {
	if !positiveIntegerPattern.MatchString(raw) {
		return 0, false
	}
	size, err := strconv.ParseInt(raw, 10, 64)
	if err != nil || size > maxConfigScopePageSize {
		return 0, false
	}
	return int(size), true
}
  ON lv.namespace = s.namespace AND lv.environment = s.environment
 AND lv.version = s.latest_version`

// scopeCountSQL counts the grouped scopes. The inner filter clauses live inside the subquery.
const scopeCountSQL = `SELECT COUNT(*) FROM (` + scopeAggregateSQL + `%s
GROUP BY v.namespace, v.environment) AS s`

func applyScopeFilter(filter ScopeFilter) (innerClause string, innerArgs []any, outerClause string, outerArgs []any) {
	if filter.Namespace != "" {
		innerClause += ` AND v.namespace = ?`
		innerArgs = append(innerArgs, filter.Namespace)
	}
	if filter.Environment != "" {
		innerClause += ` AND v.environment = ?`
		innerArgs = append(innerArgs, filter.Environment)
	}
	if filter.HasEffectiveFilter {
		if filter.HasEffective {
			outerClause += ` WHERE s.effective_version > 0`
		} else {
			outerClause += ` WHERE s.effective_version = 0`
		}
	}
	return innerClause, innerArgs, outerClause, outerArgs
}

// ListScopes returns one page of scopes that own at least one version, ordered by namespace then
// environment ascending, along with the total count matching the filter. AfterNamespace and
// afterEnvironment must be supplied together and select combinations strictly after that cursor.
// The read is a pure query: it creates no row and changes no stored record.
func (s *Store) ListScopes(ctx context.Context, filter ScopeFilter,
	afterNamespace, afterEnvironment string, limit int) (ScopePage, error) {
	page := ScopePage{Scopes: []ScopeSummary{}}
	innerClause, innerArgs, outerClause, outerArgs := applyScopeFilter(filter)

	countQuery := fmt.Sprintf(scopeCountSQL, innerClause) + outerClause
	countArgs := append(append([]any{}, innerArgs...), outerArgs...)
	if err := s.db.QueryRowContext(ctx, countQuery, countArgs...).Scan(&page.Total); err != nil {
		return ScopePage{}, fmt.Errorf("count scopes: %w", err)
	}

	cursorClause := ""
	queryArgs := append(append([]any{}, innerArgs...), outerArgs...)
	if afterNamespace != "" || afterEnvironment != "" {
		cursorClause = ` WHERE (s.namespace > ? OR (s.namespace = ? AND s.environment > ?))`
		if filter.HasEffectiveFilter {
			cursorClause = ` AND (s.namespace > ? OR (s.namespace = ? AND s.environment > ?))`
		}
		queryArgs = append(queryArgs, afterNamespace, afterNamespace, afterEnvironment)
	}
	query := fmt.Sprintf(scopeLatestJoinSQL, innerClause) + outerClause + cursorClause +
		` ORDER BY s.namespace ASC, s.environment ASC LIMIT ?`
	queryArgs = append(queryArgs, limit+1)

	rows, err := s.db.QueryContext(ctx, query, queryArgs...)
	if err != nil {
		return ScopePage{}, fmt.Errorf("list scopes: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var scope ScopeSummary
		if err := rows.Scan(
			&scope.Namespace, &scope.Environment, &scope.VersionCount, &scope.LatestVersion,
			&scope.Latest.GrayTag, &scope.Latest.RollbackOf, &scope.Latest.PromotionOf, &scope.Latest.CreatedAt,
			&scope.EffectiveVersion, &scope.EffectiveItemCount,
			&scope.GrayVersionCount, &scope.RollbackVersionCount, &scope.PromotionVersionCount,
		); err != nil {
			return ScopePage{}, fmt.Errorf("scan scope: %w", err)
		}
		scope.Latest.Namespace = scope.Namespace
		scope.Latest.Environment = scope.Environment
		scope.Latest.Version = scope.LatestVersion
		page.Scopes = append(page.Scopes, scope)
	}
	if err := rows.Err(); err != nil {
		return ScopePage{}, fmt.Errorf("iterate scopes: %w", err)
	}
	if len(page.Scopes) > limit {
		page.HasMore = true
		page.Scopes = page.Scopes[:limit]
	}

